Translate the following GNU C++0x code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

using vi = vector<int>;

void scan_int(int& x) {
    scanf("%d", &x);
}

void scan_vector(vi& v, int n) {
    v.clear();
    for (int i = 0; i < n; i++) {
        int x;
        scan_int(x);
        v.push_back(x);
    }
}

void print_int(int x) {
    printf("%d\n", x);
}

void print_int(int a, int b) {
    printf("%d %d\n", a, b);
}

void print_int(int a, int b, int c) {
    printf("%d %d %d\n", a, b, c);
}

void print_int(int a, int b, int c, int d) {
    printf("%d %d %d %d\n", a, b, c, d);
}

void print_int_no_newline(int x) {
    printf("%d", x);
}

void print_int_no_newline(int a, int b) {
    printf("%d %d", a, b);
}

void print_int_no_newline(int a, int b, int c) {
    printf("%d %d %d", a, b, c);
}

void print_int_no_newline(int a, int b, int c, int d) {
    printf("%d %d %d %d", a, b, c, d);
}

void scan_int_newline(int& x) {
    scanf("%d\n", &x);
}

void scan_int_newline(int& a, int& b) {
    scanf("%d %d\n", &a, &b);
}

void scan_int_newline(int& a, int& b, int& c) {
    scanf("%d %d %d\n", &a, &b, &c);
}

void scan_int_newline(int& a, int& b, int& c, int& d) {
    scanf("%d %d %d %d\n", &a, &b, &c, &d);
}

void print_vector(const vi& v) {
    for (size_t i = 0; i < v.size(); i++) {
        printf("%d%c", v[i], (i == v.size() - 1) ? '\n' : ' ');
    }
}

void solve() {
    int n, t;
    vi arr;
    scan_int(n);
    scan_vector(arr, n);
    sort(arr.begin(), arr.end());

    int i = 0, j = 0, max_window = 0;
    scan_int(t);

    while (j < n) {
        while (j < n && arr[j] - arr[i] <= t) {
            j++;
        }
        max_window = max(max_window, j - i);
        i++;
    }

    print_int(max_window);
}

int main() {
    solve();
    return 0;
}
